#include <cstdarg>
#include <cstdio>

double sum(int n, ...) {
  va_list ap;
  va_start(ap, n);
  double s = 0;
  for (int i = 0; i < n; ++i) s += va_arg(ap, double);
  va_end(ap);
  return s;
}

int main() {
  float f = 1.5f;
  std::printf("%g\n", sum(2, f, 2.5));
}

